export default function check({ url, statusCode, headers, body, previousState }) {
  const hops = previousState?.hops ?? 0;
  if (
    !Number.isInteger(statusCode) ||
    statusCode < 100 ||
    statusCode > 599 ||
    !Number.isInteger(hops) ||
    hops < 0
  )
    throw Error("Invalid response");
  if (
    statusCode >= 300 &&
    statusCode < 400 &&
    typeof headers?.location === "string" &&
    headers.location
  ) {
    if (hops >= 21) throw Error("Too many redirects");
    let target;
    try {
      target = new URL(headers.location, url);
    } catch {
      throw Error("Invalid redirect");
    }
    if (!["http:", "https:"].includes(target.protocol) || target.username || target.password)
      throw Error("Invalid redirect");
    return {
      state: { hops: hops + 1, nextUrl: target.toString() },
      redirect: true,
      modifications: [{ name: "redirect" }],
    };
  }
  if (statusCode < 200 || statusCode >= 300) throw Error("Cocktail request failed");
  let result;
  try {
    result = JSON.parse(body);
  } catch {
    throw Error("Invalid cocktail JSON");
  }
  const d = result?.drinks?.[0];
  if (
    typeof d?.strDrink !== "string" ||
    !d.strDrink.trim() ||
    typeof d?.strInstructions !== "string" ||
    !d.strInstructions.trim() ||
    typeof d?.strDrinkThumb !== "string"
  )
    throw Error("Cocktail response lacks name, instructions or image");
  if (!/^https?:\/\/[^/?#@\s]+(?:[/?#][^\s]*)?$/i.test(d.strDrinkThumb))
    throw Error("Invalid cocktail image URL");
  return {
    state: { hops, nextUrl: "" },
    redirect: false,
    modifications: [
      { name: "cocktail-image", image_url: d.strDrinkThumb },
      { name: "title", text: d.strDrink },
      { name: "recipe", text: d.strInstructions },
    ],
  };
}

