export default function attachment({ image }) {
  if (
    !image ||
    typeof image !== "object" ||
    image.status !== "completed" ||
    typeof image.uid !== "string" ||
    !image.uid ||
    typeof image.image_url !== "string"
  )
    throw Error("Bannerbear did not return a completed image");
  if (!/^https?:\/\/[^/?#@\s]+(?:[/?#][^\s]*)?$/i.test(image.image_url))
    throw Error("Invalid rendered image URL");
  return { attachments: [{ image_url: image.image_url }] };
}

