function readRocketMessage(message, success) {
  if (
    success !== true ||
    !message ||
    typeof message !== "object" ||
    Array.isArray(message) ||
    typeof message._id !== "string" ||
    message._id.length === 0 ||
    typeof message.rid !== "string" ||
    message.rid.length === 0 ||
    typeof message.msg !== "string"
  )
    throw new Error("Rocket.Chat did not confirm a sent message");
  return message;
}
export default function rocketChatResult({ message, success }) {
  return { message: readRocketMessage(message, success) };
}
